"use client";

import { useState, useEffect } from "react";
import { getProduits, saveProduits, Produit } from "../../lib/produits";

export default function AdminAtelier() {
  const [produits, setProduits] = useState<Produit[]>([]);
  const [form, setForm] = useState({ nom: "", categorie: "", prix: "", etat: "Très bon état" });
  const [edition, setEdition] = useState<number | null>(null);

  useEffect(() => {
    setProduits(getProduits());
  }, []);

  const supprimer = (id: number) => {
    if (window.confirm("Voulez-vous vraiment supprimer cette pépite ?")) {
      const updated = produits.filter((p) => p.id !== id);
      setProduits(updated);
      saveProduits(updated);
    }
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!form.nom || !form.categorie || !form.prix) return;

    let updated: Produit[];
    if (edition !== null) {
      updated = produits.map((p) =>
        p.id === edition
          ? { ...p, nom: form.nom, categorie: form.categorie, prix: Number(form.prix), etat: form.etat }
          : p
      );
      setEdition(null);
    } else {
      const nouveau: Produit = {
        id: Date.now(),
        nom: form.nom,
        categorie: form.categorie,
        prix: Number(form.prix),
        etat: form.etat,
      };
      updated = [...produits, nouveau];
    }
    setProduits(updated);
    saveProduits(updated);
    setForm({ nom: "", categorie: "", prix: "", etat: "Très bon état" });
  };

  const editer = (p: Produit) => {
    setForm({ nom: p.nom, categorie: p.categorie, prix: String(p.prix), etat: p.etat });
    setEdition(p.id);
  };

  return (
    <main className="min-h-screen bg-[#fdf6f0] text-[#3E2723]">
      <section className="py-12 px-4 max-w-4xl mx-auto">
        <h1 className="text-3xl font-serif font-bold text-amber-900 text-center mb-8">
          🔧 Gestion de l&apos;Atelier
        </h1>

        <form onSubmit={handleSubmit} className="bg-white rounded-2xl shadow-md p-6 mb-10 border border-amber-200">
          <h2 className="text-lg font-bold text-amber-800 mb-4">
            {edition !== null ? "✏️ Modifier" : "➕ Ajouter une pépite"}
          </h2>
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <input type="text" placeholder="Nom de l'objet" value={form.nom} onChange={(e) => setForm({ ...form, nom: e.target.value })} className="border border-stone-300 rounded-lg p-2" />
            <input type="text" placeholder="Catégorie" value={form.categorie} onChange={(e) => setForm({ ...form, categorie: e.target.value })} className="border border-stone-300 rounded-lg p-2" />
            <input type="number" placeholder="Prix (€)" value={form.prix} onChange={(e) => setForm({ ...form, prix: e.target.value })} className="border border-stone-300 rounded-lg p-2" />
            <select value={form.etat} onChange={(e) => setForm({ ...form, etat: e.target.value })} className="border border-stone-300 rounded-lg p-2">
              <option>Très bon état</option>
              <option>Bon état</option>
              <option>Dans son jus</option>
            </select>
          </div>
          <button type="submit" className="mt-4 bg-amber-800 text-white px-6 py-2 rounded-full font-semibold hover:bg-amber-700 transition">
            {edition !== null ? "💾 Mettre à jour" : "✨ Publier la pépite"}
          </button>
          {edition !== null && (
            <button type="button" onClick={() => { setForm({ nom: "", categorie: "", prix: "", etat: "Très bon état" }); setEdition(null); }} className="ml-3 text-stone-500 underline">
              Annuler
            </button>
          )}
        </form>

        <div className="space-y-3">
          {produits.map((p) => (
            <div key={p.id} className="bg-white rounded-xl shadow-sm p-4 flex justify-between items-center border border-stone-100">
              <div>
                <p className="font-semibold">{p.nom}</p>
                <p className="text-xs text-stone-400">{p.categorie} • {p.prix}€ • {p.etat}</p>
              </div>
              <div className="flex gap-2">
                <button onClick={() => editer(p)} className="text-blue-500 hover:underline text-sm">✏️</button>
                <button onClick={() => supprimer(p.id)} className="text-red-500 hover:underline text-sm">🗑️</button>
              </div>
            </div>
          ))}
          {produits.length === 0 && (
            <p className="text-center text-stone-400 py-8">Aucun produit dans l&apos;atelier.</p>
          )}
        </div>
      </section>
    </main>
  );
}